INSERT INTO testimonios (id,autor,cargo,texto,proyecto_slug,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'María Elena Quispe','Propietaria · Baños del Inca','Nos entregaron la casa en el plazo prometido y el presupuesto no cambió. Siempre hubo alguien en obra que nos explicaba cada avance.','casa-campestre-banos-del-inca',0,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO testimonios (id,autor,cargo,texto,proyecto_slug,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Roberto Chávez','Administrador · Edificio Jr. Amazonas','Lo mejor fue tener planos, licencia y obra con el mismo equipo. Nos ahorramos meses de ida y vuelta entre profesionales.','edificio-multifamiliar-amazonas',1,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO testimonios (id,autor,cargo,texto,proyecto_slug,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Ana Lucía Ramírez','Empresaria · Cajamarca','Remodelaron la casona respetando su estilo y sin parar mi negocio. El resultado superó lo que esperaba.','remodelacion-casona-plaza-de-armas',2,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Un solo equipo, de principio a fin','Planos, permisos, obra y acabados con el mismo equipo responsable.',TRUE,0,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Supervisión técnica en cada etapa','Un ingeniero residente controla calidad, seguridad y avance de tu obra.',TRUE,1,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Presupuesto claro y por escrito','Sabes cuánto cuesta cada partida antes de empezar; los cambios se aprueban contigo.',TRUE,2,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Plazos acordados','Cronograma firmado con fechas de entrega y reportes de avance periódicos.',FALSE,3,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Garantía posventa','Atendemos cualquier observación de la obra durante el primer año.',FALSE,4,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO garantias (id,titulo,texto,en_hero,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Saneamiento y trámites incluidos','Te acompañamos con licencias, habilitaciones y regularización del predio.',FALSE,5,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO pasos_proceso (id,titulo,texto,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Consulta y terreno','Visitamos el lugar, revisamos la situación legal y el levantamiento topográfico, y definimos qué es posible construir.',0,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO pasos_proceso (id,titulo,texto,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Diseño y planos','Elaboramos los planos de arquitectura y especialidades, y gestionamos los permisos y las habilitaciones necesarias.',1,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO pasos_proceso (id,titulo,texto,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Ejecución y supervisión','Construimos con supervisión técnica en cada etapa, para cuidar plazos, calidad y presupuesto.',2,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO pasos_proceso (id,titulo,texto,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'Entrega','Revisamos acabados y detalles contigo y te entregamos la obra lista para habitarla.',3,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Cuánto cuesta construir una casa en Cajamarca?','Depende del tamaño, los acabados y el terreno. Tras una visita sin costo te entregamos un presupuesto por escrito, partida por partida.','HOME',0,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Cuánto demora una obra?','Una vivienda de 150 a 250 m² suele tomar entre 7 y 10 meses desde el inicio de obra. Los plazos de licencia dependen de la municipalidad.','HOME',1,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Se encargan de la licencia y los permisos?','Sí. Elaboramos los planos y gestionamos la licencia de edificación y, si hace falta, el saneamiento físico legal del terreno.','HOME',2,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Trabajan fuera de la ciudad de Cajamarca?','Sí, en toda la región: Baños del Inca, Namora, La Encañada, Celendín, Jaén y otras provincias.','HOME',3,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Cómo se paga la obra?','Por valorizaciones según el avance real de la obra, con adelanto inicial acordado en el contrato.','HOME',4,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Qué incluye el servicio de supervisión?','Visitas técnicas programadas, control de materiales y calidad, verificación de metrados e informes de avance.','SERVICIOS',5,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Pueden ejecutar un diseño que ya tengo?','Sí. Revisamos tus planos, ajustamos lo necesario y los ejecutamos con presupuesto propio.','SERVICIOS',6,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO faqs (id,pregunta,respuesta,ambito,orden,activo,fecha_creacion,fecha_actualizacion) VALUES (gen_random_uuid(),'¿Cuánto tarda el saneamiento físico legal?','Entre 2 y 6 meses según el estado de la documentación y los tiempos de Registros Públicos.','SERVICIOS',7,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
